"""Blocos HTML de imagens e créditos, partilhados pelo gerador estático."""
from html import escape as e
import json
from pathlib import Path
from conteudos.recursos import FOTOS_TECNICAS, PRODUTOS, POR_ID, CATALOGO
ROOT=Path(__file__).resolve().parents[1]

def tecnica(id,prefix='../'):
    f=FOTOS_TECNICAS[id]
    return f'''<figure class="technique-photo"><div class="technique-photo-frame"><img src="{prefix}assets/tecnicas/{id}.webp" alt="{e(f['alt'])}" width="{f['width']}" height="{f['height']}" loading="lazy" decoding="async"></div><figcaption>Exemplo ilustrativo de terceiros: {e(f['titulo'].lower())}. Não representa a produção da Nobrinde. <span>Fotografia: {e(f['autor'])} · <a href="{prefix}creditos-imagens.html#{id}">{f['licenca']} — créditos e alterações</a></span></figcaption></figure>'''

def exemplos(ids,prefix='../',heading=True):
    sizes={p['id']:p for p in json.loads((ROOT/'assets/produtos/manifesto.json').read_text(encoding='utf-8'))}
    items=''
    for id in ids:
        p=POR_ID[id];size=sizes[id]
        items+=f'''<article class="product-example" id="produto-{id}"><figure><div class="product-photo-frame"><img src="{prefix}assets/produtos/{p['ficheiro']}" alt="{e(p['alt'])}" width="{size['width']}" height="{size['height']}" loading="lazy" decoding="async"></div><figcaption>Imagem do catálogo · Ref. {p['ref']}</figcaption></figure><div class="product-example-copy"><h3>{e(p['nome'])} <span>{p['ref']}</span></h3><ul>{''.join('<li>'+e(t)+'</li>' for t in p['factos'])}</ul><p>{e(p['leitura'])}</p><p class="catalogue-source"><a href="{prefix}creditos-imagens.html#catalogo-{id}">Catálogo 2026 · PDF p. {p['pdf']} · página impressa {p['impressa']}</a></p></div></article>'''
    grid='<div class="product-grid">'+items+'</div>'
    if not heading:return grid
    return '<section class="catalogue-examples" id="exemplos-catalogo"><h2>Exemplos documentados no catálogo</h2><p class="catalogue-intro">Referências para compreender materiais e variantes. As características correspondem à edição de 2026; não indicam disponibilidade atual nem trabalhos realizados pela Nobrinde.</p>'+grid+'</section>'

def creditos():
    html='<nav class="crumb" aria-label="Percurso"><a href="index.html">Início</a> / Créditos de imagens</nav><div class="page-intro"><span class="eyebrow">Fontes e atribuições</span><h1>Créditos de imagens</h1><p>Identificação das fotografias, das suas fontes e das alterações realizadas para esta biblioteca.</p></div><section><h2>Fotografias das técnicas</h2><p>São exemplos ilustrativos de terceiros. Não mostram instalações, equipamentos ou trabalhos da Nobrinde e não implicam o endosso dos autores.</p><div class="credits-grid">'
    for id,f in FOTOS_TECNICAS.items():
        share=' A versão adaptada mantém a licença '+f['licenca']+'.' if 'BY-SA' in f['licenca'] else ''
        html+=f'''<article class="credit-card" id="{id}"><img src="assets/tecnicas/{id}.webp" alt="{e(f['alt'])}" width="{f['width']}" height="{f['height']}" loading="lazy"><h3>{f['titulo']}</h3><dl><dt>Autor</dt><dd>{e(f['autor'])}</dd><dt>Fonte</dt><dd><a href="{f['fonte']}">Fotografia original no Wikimedia Commons</a></dd><dt>Licença</dt><dd><a href="{f['licenca_url']}">{f['licenca']}</a></dd><dt>Alterações</dt><dd>Redimensionamento e conversão de JPEG para WebP, sem recorte.{share}</dd></dl></article>'''
    html+='</div><p class="catalogue-intro">Atribuições conforme o ficheiro LEIA-ME-creditos.md fornecido com as imagens. A atribuição da imagem CC0 é mantida para transparência. Estas licenças aplicam-se às respetivas fotografias, não às imagens do catálogo nem ao site completo.</p></section>'
    html+=f'<section id="catalogo"><h2>Fotografias de produtos</h2><p>Fonte: <cite>{CATALOGO}</cite>, ficheiro fornecido pela equipa. As fotografias individuais foram extraídas dos objetos de imagem do PDF, compostas sobre fundo branco quando necessário e convertidas para WebP. Não foram ampliadas nem recortadas; a fotografia Stiles foi reduzida para 1200 px no lado maior.</p><p>Autoria individual e licença de reutilização: não identificadas no ficheiro recebido. Não se atribui uma licença Creative Commons a estas fotografias. As marcas e imagens de exemplo presentes nos artigos pertencem à apresentação do catálogo, sem indicar produção da Nobrinde.</p><p>A numeração PDF começa na primeira página do ficheiro. É apresentada também a numeração impressa, que difere ao longo do documento.</p><div class="credit-product-list">'
    for p in PRODUTOS:
        html+=f'<article id="catalogo-{p["id"]}"><h3>{p["nome"]} · {p["ref"]}</h3><p>Fotografia e características: PDF p. {p["pdf"]}; página impressa {p["impressa"]}.</p><a href="assets/produtos/{p["ficheiro"]}">Ver a fotografia extraída</a></article>'
    html+='</div></section><section id="tampografia-provisoria"><h2>Imagens provisórias de tampografia</h2><p>Ficheiros fornecidos pela equipa: autoria, fonte original e licença não identificadas. <strong>Origem e autorização de publicação por confirmar.</strong> Não são atribuídos à Nobrinde. Apresentação sem ampliação, recorte ou outras alterações.</p><ul><li>processo-tampografia-6-passos.jpg — esquema usado em «Como funciona».</li><li>tampoes-silicone-tampografia.jpg — fotografia usada em «Componentes».</li><li>maquina-tampografia-exemplos.jpg — montagem ilustrativa de terceiros usada em «Equipamentos».</li><li>processo-tampografia-5-passos.jpg — guardado na pasta; não mostrado no artigo.</li></ul><p>Estes ficheiros não herdam a licença da fotografia de tampografia creditada acima. As marcas visíveis não comprovam autoria nem autorização de reutilização.</p><div>'
    html+='</div></section><section id="serigrafia-provisoria"><h2>Imagens provisórias de serigrafia</h2><p>Origem e autorização de publicação por confirmar. Estas imagens não representam equipamentos da Nobrinde nem herdam a licença da fotografia principal.</p><ul><li>maquina-carrossel-serigrafia-verde.jpg — exemplo ilustrativo na secção Equipamento, sem ampliação ou recorte.</li><li>maquina-carrossel-serigrafia-azul.jpg — reservada para a página de máquinas.</li><li>funcionamento-tela-serigrafia.jpg — não publicada; substituída por um esquema legível em português.</li><li>etapas-serigrafia-referencia.jpg — referência interna, não publicada.</li></ul></section>'
    html+='<section id="uv-provisoria"><h2>Imagens provisórias de impressão UV</h2><p>Origem e autorização de publicação por confirmar. Não representam instalações ou equipamentos da Nobrinde. A licença da fotografia principal não se estende a estes ficheiros.</p><ul><li>impressao-uv-em-curso.jpg — junto dos passos.</li><li>impressora-uv-mesa.jpg — equipamento ilustrativo.</li><li>impressao-uv-painel-colorido.jpg — exemplo de impressão plana.</li><li>impressora-uv-grande-formato.jpg — reservada para a página de máquinas; representa outra escala de trabalho e não é exibida no guia da técnica.</li></ul><p>As três imagens apresentadas conservam as proporções e não são ampliadas.</p></section>'
    return html+'<section id="esquemas-industria"><h2>Esquemas da indústria</h2><p>Cronologia e esquemas originais desta biblioteca, construídos em HTML e CSS. São representações simplificadas, sem fotografias de instalações. As cinco fotografias das técnicas são também utilizadas nos guias de máquinas, com os mesmos autores, licenças e alterações indicados acima.</p></section>'
